begin;
select plan(21);
insert into auth.users(id) values ('5a000000-0000-4000-8000-000000000001');
insert into auth.sessions(id,user_id) values ('6a000000-0000-4000-8000-000000000001','5a000000-0000-4000-8000-000000000001');
insert into public.staff_members(user_id,active,display_name) values ('5a000000-0000-4000-8000-000000000001',true,'Funcionária original');
insert into public.animals(id,name,species,sex,size,approximate_age) values ('7a000000-0000-4000-8000-000000000001','Fixture aplicação','dog','female','small','2');
create temporary table completion_test(kind text,value jsonb);grant all on completion_test to authenticated;
select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000001","session_id":"6a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
insert into completion_test select 'saved',public.save_medication_treatment(repeat('s',32),'{"animal_id":"7a000000-0000-4000-8000-000000000001","medication_name":"Exemplo","schedule_mode":"fixed_times","starts_on":"2020-01-01","starts_time":"08:00","ends_on":"2020-01-01","ends_time":"20:00","fixed_times":["08:00","09:00","10:00"]}');
reset role;
insert into completion_test select 'before',jsonb_build_object('now',clock_timestamp(),'counter',agenda_version) from private.medication_agenda_state;
insert into completion_test select 'due',jsonb_build_object('id',id) from public.medication_applications where treatment_id=(select (value#>>'{result,treatment,id}')::uuid from completion_test where kind='saved') order by scheduled_at limit 1;
update public.medication_applications set scheduled_at='2100-01-01T12:00:00Z' where scheduled_at='2020-01-01T12:00:00Z' and treatment_id=(select (value#>>'{result,treatment,id}')::uuid from completion_test where kind='saved');
update public.medication_applications set state='cancelled',cancelled_at=now(),cancelled_reason='treatment_stopped' where scheduled_at='2020-01-01T13:00:00Z' and treatment_id=(select (value#>>'{result,treatment,id}')::uuid from completion_test where kind='saved');
set local role authenticated;
insert into completion_test select 'done',public.complete_medication_application(repeat('t',32),(select (value->>'id')::uuid from completion_test where kind='due'),1);
select is((select value#>>'{result,application,state}' from completion_test where kind='done'),'completed','server confirms completed state');
select is((select value#>>'{result,application,performed_by}' from completion_test where kind='done'),'5a000000-0000-4000-8000-000000000001','actor comes from session');
select is((select value#>>'{result,application,actor_label}' from completion_test where kind='done'),'Funcionária original','staff display name recorded');
select is((select (value#>>'{result,application,version}')::int from completion_test where kind='done'),2,'application version increments once');
select ok((select (value#>>'{result,application,performed_at}')::timestamptz >= (select (value->>'now')::timestamptz from completion_test where kind='before') from completion_test where kind='done'),'actual timestamp generated by server');
select is((select value#>>'{result,event,occurred_at}' from completion_test where kind='done'),(select value#>>'{result,application,performed_at}' from completion_test where kind='done'),'event and application share actual time');
select is(public.complete_medication_application(repeat('t',32),(select (value->>'id')::uuid from completion_test where kind='due'),1),(select value from completion_test where kind='done'),'replay preserves original receipt');
select is(public.get_medication_operation(repeat('t',32)),(select value from completion_test where kind='done'),'receipt reconciles confirmed completion');
select throws_ok($$select public.complete_medication_application(repeat('t',32),(select (value->>'id')::uuid from completion_test where kind='due'),2)$$,'PT409','operation_conflict','same key changed version denied');
select throws_ok($$select public.complete_medication_application(repeat('u',32),(select (value->>'id')::uuid from completion_test where kind='due'),1)$$,'PT409','stale_version','stale version denied');
select throws_ok($$select public.complete_medication_application(repeat('u',32),(select (value->>'id')::uuid from completion_test where kind='due'),2)$$,'PT409','already_completed_or_cancelled','new key cannot complete twice');
select throws_ok($$select public.complete_medication_application(repeat('v',32),(select id from public.medication_applications where treatment_id=(select (value#>>'{result,treatment,id}')::uuid from completion_test where kind='saved') and scheduled_at>'2099-01-01'),1)$$,'PT409','not_due','future completion denied');
select throws_ok($$select public.complete_medication_application(repeat('w',32),(select id from public.medication_applications where treatment_id=(select (value#>>'{result,treatment,id}')::uuid from completion_test where kind='saved') and state='cancelled'),1)$$,'PT409','already_completed_or_cancelled','cancelled completion denied');
select throws_ok($$select public.complete_medication_application('bad',null,0)$$,'22023','invalid_payload','invalid command denied');
select throws_ok($$select public.complete_medication_application(repeat('x',32),'9a000000-0000-4000-8000-000000000001',1)$$,'PT404','not_found','missing application denied');
reset role;
select is((select agenda_version-(select (value->>'counter')::bigint from completion_test where kind='before') from private.medication_agenda_state),1::bigint,'only committed mutation increments agenda');
select is((select count(*)::int from public.medication_application_events where application_id=(select (value->>'id')::uuid from completion_test where kind='due')),1,'replay and errors never duplicate event');
update public.staff_members set display_name='Nome alterado' where user_id='5a000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.get_medication_application_history((select (value->>'id')::uuid from completion_test where kind='due'),null)#>>'{application,actor_label}','Funcionária original','history retains original staff label');
reset role;
update public.staff_members set active=false where user_id='5a000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.complete_medication_application(repeat('t',32),(select (value->>'id')::uuid from completion_test where kind='due'),1)$$,'42501','staff_required','revoked staff cannot replay');
select throws_ok($$select public.get_medication_operation(repeat('t',32))$$,'42501','staff_required','revoked staff cannot reconcile');
reset role;
set local role anon;
select throws_ok($$select public.complete_medication_application(repeat('t',32),'9a000000-0000-4000-8000-000000000001',1)$$,'42501',null,'visitor cannot complete');
reset role;
select * from finish();rollback;
